-- Athena saved query (Product_B2C_Intl)
-- ID: 8c333ad5-5647-4cd5-9973-3e16dec3088a
-- Name: 0 tuple click share - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH offer_tuple AS ( SELECT DISTINCT src_id, dest_id FROM "user_interaction"."search_route_details" WHERE __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-27 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND country = 'IND' ), srp_deduped AS ( SELECT DISTINCT CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, s.mri_session_id, s.route_id, s.user_type, s.os, s.channel, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) > 2 THEN '3. DBD 2+' ELSE 'Others' END AS search_day, CAST(doj AS VARCHAR) AS doj, -- s.src_id, s.dest_id, MIN(offset + position + 1) AS position FROM "user_interaction"."search_route_details" s WHERE s.__time >= TIMESTAMP '2025-12-31 18:30:00' AND s.__time < TIMESTAMP '2026-01-27 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND s.os = 'Android' AND s.country = 'IND' GROUP BY 1,2,3,4,5,6,7,8 ), sl_deduped AS ( SELECT mri_session_id, route_id, doj, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-27 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2,3 ), confirm_deduped AS ( SELECT mri_session_id, route_id, tin, CAST(doj AS VARCHAR) AS doj, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-27 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2,3,4 ) SELECT CASE WHEN srp.doi >= DATE '2026-01-01' AND srp.doi < DATE '2026-01-07' THEN 'Pre DBS' WHEN srp.doi >= DATE '2026-01-07' AND srp.doi < DATE '2026-01-28' THEN CAST(srp.doi AS VARCHAR) ELSE 'Other Period' END AS doi, 'All India' AS route_cohort, srp.user_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, search_day, COUNT(DISTINCT CASE WHEN srp.position = 1 THEN sl.mri_session_id END) AS Top_Tuple_sl_land_sessions, COUNT(DISTINCT sl.mri_session_id) all_sl_lands, COUNT(DISTINCT srp.mri_session_id) all_srp_sessions, COUNT(DISTINCT CASE WHEN srp.position = 1 THEN c.mri_session_id END) AS Top_Tuple_confirm_sessions, COUNT(DISTINCT c.mri_session_id) overall_confirm_sessions, COUNT(DISTINCT CASE WHEN srp.position = 1 THEN c.tin END) AS Top_Tuple_tins, COUNT(DISTINCT c.tin) overall_confirm_tins FROM srp_deduped srp -- INNER JOIN offer_tuple ot ON srp.src_id = ot.src_id AND srp.dest_id = ot.dest_id LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id AND srp.doj = sl.doj LEFT JOIN confirm_deduped c ON srp.mri_session_id = c.mri_session_id AND srp.route_id = c.route_id AND srp.doj = c.doj GROUP BY 1,2,3,4,5
